use vybe_runtime::{Chunk,Value,VM};
fn compile(s:&str)->Vec<Chunk>{static INIT:std::sync::Once=std::sync::Once::new();INIT.call_once(vybe_language_php::register);let ast=vybe_language_php::parse(&format!("<?php {s}")).unwrap();let p=vybe_compiler::profile::parse_profile(vybe_language_php::profile_source()).unwrap();vybe_compiler::Compiler::with_profile(p).compile(&ast).unwrap()}
fn native(c:&[Chunk],label:&str){let b=vybe_platform_wasm::write_wasm(c);if let Err(e)=wasmparser::Validator::new_with_features(wasmparser::WasmFeatures::all()).validate_all(&b){std::fs::write(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(format!("{label}-full-native-failure.wasm")),b).unwrap();panic!("{label} strictfullnative:{e}");}}
fn run(s:&str,label:&str)->Value{let c=compile(s);native(&c,label);assert!(c.iter().any(|c|c.name=="__stdlib_levenshtein"));let mut v=VM::new();vybe_compiler::primitives::platforms::register_platforms_all(&mut v);v.run(c).unwrap()}
#[test]fn actual_ascii_scalar_empty_and_boundary_controls(){for(s,w)in [("return levenshtein('kitten','sitting');",3.),("return levenshtein('','');",0.),("return levenshtein('a','');",1.),("return levenshtein(123,124);",1.),("return levenshtein(true,null);",1.),("return levenshtein('aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb');",32.),("return levenshtein('aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb');",33.)]{assert_eq!(run(s,"ascii"),Value::F64(w),"{s}");}}
#[test]fn actual_argument_evaluation_and_coercion_order(){let s=r#"$trace=''; class LevInput {public $value;public $name;function __construct($n,$s){$this->name=$n;$this->value=$s;}function __toString(){global $trace;$trace.=$this->name;return $this->value;}}function left(){global $trace;$trace.='l';return new LevInput('A','kitten');}function right(){global $trace;$trace.='r';return new LevInput('B','sitting');}$answer=levenshtein(left(),right());return $answer.':'.$trace;"#;assert_eq!(run(s,"order"),Value::String("3:lrAB".into()));}
#[test]fn actual_partial_throw_preserves_coercion_order(){let s=r#"$trace='';class LevFail {function __toString(){global $trace;$trace.='A';throw new Exception('lev-stop');}}class LevLater {function __toString(){global $trace;$trace.='B';return 'x';}}try{levenshtein(new LevFail(),new LevLater());return 'wrong';}catch(Exception $e){return $trace.':'.$e->getMessage();}"#;assert_eq!(run(s,"throw"),Value::String("A:lev-stop".into()));}
#[test]fn actual_unicode_fallback_and_public_name_collision(){assert_eq!(run("return levenshtein('😀','🦀');","unicode"),Value::F64(0.),"established VM surrogate-folding gap, not PHP byte semantics");let s="function __stdlib_levenshtein($a,$b){return 'poison';} return levenshtein('kitten','sitting').':'.__stdlib_levenshtein('x','y');";assert_eq!(run(s,"collision"),Value::String("3:poison".into()));}
